using System;

namespace Bodu.Extensions;

public partial class DateOnlyExtensionsTests
{

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.FirstDateOfWeekInMonth" />, when Called, returns the expected value.
    /// </summary>
    [TestMethod]
    [DynamicData(nameof(DateTimeExtensionsTests.FirstDateOfWeekInMonthTestData), typeof(DateTimeExtensionsTests))]
    public void FirstDateOfWeekInMonth_WhenCalled_ShouldReturnExpectedDate(DateTime inputDateTime, DayOfWeek dayOfWeek, DateTime expectedDateTime)
    {
        DateOnly input = DateOnly.FromDateTime(inputDateTime);
        DateOnly expected = DateOnly.FromDateTime(expectedDateTime);

        DateOnly actual = input.FirstDateOfWeekInMonth(dayOfWeek);

        Assert.AreEqual(expected, actual);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.FirstDateOfWeekInMonth" />, when InvalidDayOfWeek, throws <see cref="ArgumentOutOfRangeException" />.
    /// </summary>
    [TestMethod]
    public void FirstDateOfWeekInMonth_WhenInvalidDayOfWeek_ShouldThrowExactly()
    {
        DateOnly input = new DateOnly(2024, 4, 1);
        var invalidDay = (DayOfWeek)999;

        Assert.ThrowsExactly<ArgumentOutOfRangeException>(() =>
        {
            _ = input.FirstDateOfWeekInMonth(invalidDay);
        });
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.FirstDateOfWeekInMonth" />, when UsingMaxValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void FirstDateOfWeekInMonth_WhenUsingMaxValue_ShouldReturnValidResult()
    {
        DateOnly actual = DateOnly.MaxValue.FirstDateOfWeekInMonth(DayOfWeek.Friday);

        Assert.IsTrue(actual <= DateOnly.MaxValue);
    }

    /// <summary>
    /// Verifies that <see cref="DateOnlyExtensions.FirstDateOfWeekInMonth" />, when UsingMinValue, returns <see langword="true" />.
    /// </summary>
    [TestMethod]
    public void FirstDateOfWeekInMonth_WhenUsingMinValue_ShouldReturnValidResult()
    {
        DateOnly actual = DateOnly.MinValue.FirstDateOfWeekInMonth(DayOfWeek.Monday);

        Assert.IsTrue(actual >= DateOnly.MinValue && actual <= DateOnly.MinValue.AddMonths(1).AddDays(-1));
    }

}
